const FIRST: u32 = 0x3100;

pub(super) fn contains(world: bool, c: char) -> bool {
    let Some(offset) = (c as u32)
        .checked_sub(FIRST)
        .filter(|&value| value < 0x10000 - FIRST)
    else {
        return false;
    };
    let table = if world { &WORLD } else { &LEGACY };
    table[(offset / 64) as usize] & (1u64 << (offset % 64)) != 0
}

